const ownership=(r.execution.logOnlyGateOwnership??[]).filter(x=>x.receiptGroupId===g.id);
need(ownership.length===1 && ownership[0].executionPointer==="/execution/priorExecution" &&
  ownership[0].stepNumber===22, "explicit original log ownership "+g.id);
const producer=at(r,ownership[0].executionPointer);
need(producer.expectedRunId===38015134511 && producer.expectedWorkflowId===378853677 &&
  producer.expectedHeadSha===r.source.sourceRef && producer.compilerJobId===114103608774 &&
  producer.compilerConclusion==="cancelled" && producer.providerConclusion==="skipped",
  "preserved original execution "+g.id);
need(logs.length>0 && logs.every(x=>x.conclusion==="success" &&
  x.stepNumber===ownership[0].stepNumber && x.workflowBlob===producer.workflowSourceBlob &&
  x.jobId===producer.compilerJobId && x.runId===producer.expectedRunId &&
